94hkh4gc1jligiiw.jpg',NULL,'APPROVED',NULL,0,0,0,0,32,NULL,1,'2026-08-28 01:07:10','2026-08-28 03:30:42','["TGĐ-001","PTGĐ-002","GĐ-003","PGĐ-004","202608001","KG-LEAD-01"]',NULL,NULL,NULL,NULL,'Nhân viên',8,2026,'','','','SN256002,SN256026',1000,'THOI_GIAN',261,132,1613,'KZ-2026-KG2-MUI-0001',NULL,'VP2_SKECHERS','PHE_DUYET','PENDING','201809012','2026-08-28 03:30:42',NULL,'CHO_PHE_DUYET',0,1000,1612500,'Một triệu sáu trăm mười hai ngàn năm trăm đồng',NULL,NULL,0,0,0,0,0);
