INSERT INTO "ci_kaizen_proposals" ("id","code","title","category","category_label","registration_type","sub_status","region","department","factory","proposer_name","proposer_emp_code","dept_code","before_description","after_solution","saved_seconds","before_image_url","after_image_url","attachments_json","status","award_title","score_points","avg_rating","rating_count","vote_count","view_count","rejection_reason","version","created_at","updated_at","required_reviewer_ids_json","average_score","evaluated_at","comments","review_comment","proposer_position","proposer_month","proposer_year","hr_suggestor","customer","product_group","product_code","quantity","pricing_direction","time_before_seconds","time_after_seconds","efficiency_value_vnd","legacy_code","team_code","plant_code","approval_status","evaluation_result","approved_by","approved_at","evaluated_by","review_status","is_archived","pair_quantity","total_savings_vnd","total_savings_words","before_video_url","after_video_url","cost_before","cost_after","chi_phi_truoc","chi_phi_sau","tong_tien_tiet_kiem") VALUES('ci_1790329655995_6sg7p','KZ-2026-PHNG-BPHN-0028','Tạo Web App quản lý hồ sơ lao động, kiểm tra định biên và thẩm tra hồ sơ tuyển dụng online','AUTOMATION','6.Tự động hoá + 3.Tăng Năng suất','THI_DUA','CHO_DANH_GIA','Phòng nhân sự','Bộ Phận Nhân Sự & Hành Chính (HR)','Phòng nhân sự','Phù Uyên Phương','401510025','SK','Khi đi đánh giá tay nghề CN (hết thời gian học việc hoặc đăng ký điều chuyển tháng) khi có phát sinh NLĐ thực tế làm vị trí khác với đăng ký đào tạo. Khi đó phải gọi điện nhờ NV Nhân Sự cùng phòng kiểm tra số lượng hiện có của vị trí đó và định biên đã đủ hay chưa để tiếp tục đánh giá => mất thời gian chờ đợi; Xảy ra tình trạng NLĐ lành nghề test tay nghề dùm cho NLĐ khác; NV Tuyển dụng phải dùng laptop để kiểm tra hồ sơ nộp xin việc, nếu kẹt laptop phải chờ lên máy tính kiểm tra => không phản hồi tại chỗ cho NLĐ đến xin việc','Web App dùng được trên điện thoại để kiểm tra nhanh chuyền/tổ thiếu hay thừa lao động theo định biên khi đi đánh giá tay nghề Công nhân. Xem nhanh hình ảnh và xác nhận đúng NLĐ được đánh giá tay nghề để tránh nhầm người hoặc thi hộ (khi NLĐ quên mang theo thẻ tên). Ngoài ra Web còn tích hợp tính năng giúp NV Tuyển dụng kiểm tra nhanh hồ sơ NLĐ đến nộp có nằm trong Blacklist không và quá trình làm việc trước đó, mà không phải dùng laptop đăng nhập SAP và danh sách trích ngang để xem. Đối tượng sử dụng: Phòng Nhân Sự - Trợ lý GĐ - Thống kê lao động PX',270,'https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790328386/fqy6zxh1dfhh4fbaesax.png,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790328386/b34fxj6bluh6ajgmsybu.png,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790329423/go8ooquciude92rmsidt.png','https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790328885/orb4rckmhxzrers4wdyv.png','["https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790328885/orb4rckmhxzrers4wdyv.png","https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790328885/dcavisavkgtxnrajq2kj.png","https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790328885/cklhrlnszzkqgoucgwdk.png"]','APPROVED',NULL,0,0,0,0,15,NULL,1,'2026-09-25 09:47:36','2026-09-26 01:06:07','["TGĐ-001","PTGĐ-002","GĐ-003","PGĐ-004","202608001"]',NULL,NULL,NULL,'Đã phê duyệt tính khả thi (Bước 3)','Nhân viên',9,2026,'','','','',30,'THOI_GIAN',300,30,3375,'KZ-2026-PHNG-BPHN-0028',NULL,'VP2_SKECHERS','PHE_DUYET','PENDING','Kiều Thanh Vũ','2026-09-26 01:06:07',NULL,'CHO_DANH_GIA',0,30,101250,'Một trăm lẻ một nghìn hai trăm năm mươi đồng',NULL,NULL,0,0,0,0,0);
