INSERT INTO "ci_kaizen_proposals" ("id","code","title","category","category_label","registration_type","sub_status","region","department","factory","proposer_name","proposer_emp_code","dept_code","before_description","after_solution","saved_seconds","before_image_url","after_image_url","attachments_json","status","award_title","score_points","avg_rating","rating_count","vote_count","view_count","rejection_reason","version","created_at","updated_at","required_reviewer_ids_json","average_score","evaluated_at","comments","review_comment","proposer_position","proposer_month","proposer_year","hr_suggestor","customer","product_group","product_code","quantity","pricing_direction","time_before_seconds","time_after_seconds","efficiency_value_vnd","legacy_code","team_code","plant_code","approval_status","evaluation_result","approved_by","approved_at","evaluated_by","review_status","is_archived","pair_quantity","total_savings_vnd","total_savings_words","before_video_url","after_video_url","cost_before","cost_after","chi_phi_truoc","chi_phi_sau","tong_tien_tiet_kiem") VALUES('ci_1790846177097_7m5ax','KZ-2026-HTD-DE-0001','Thiết kế file logo để chuyển đổi công nghệ IN CHUYỂN sang IN MÁY TRỰC TIẾP cho logo đế P563','EQUIPMENT','7.MMTB CCDC','THI_DUA','CHO_REVIEW','Hoàn thiện đế','Xưởng Hoàn Thiện Đế - Line Sơn & Ép','Hoàn thiện đế','Văn Ngọc Tính','401712018','SK',replace('Logo đế P563 sản xuất bằng công nghệ IN CHUYỂN (in tem chuyển ở xưởng In-Ép, sau đó giao qua Hoàn thiện Đế ủi nhiệt lên bề mặt viền đế)\nNhược điểm:\n- Tốn giấy in chuyển\n- Tốn công in tem ở xưởng In-Ép & công giao nhận logo từ xưởng In-Ép qua Hoàn thiện Đế\n- Rủi ro chất lượng sản phẩm: Logo sau khi in chuyển, phải ủi nhiệt trong 5-7 ngày, nếu để tồn quá hạn sẽ ảnh hưởng độ bám dính','\n',char(10)),replace('Lấy file quy cách logo, thiết kế lại  độ rộng của nét chữ cho khuôn in máy, để lắp đặt IN MÁY TRỰC TIẾP tại Hoàn thiện Đế\nƯu điểm:\n- Không cần in tem chuyển ở xưởng In-Ép, tiết kiệm công & giấy in chuyển\n- Đảm bảo chất lượng sản phẩm: Khi có KHSX thì mới đổ mực vào in, đảm bảo độ bám dính\nSố lượng đơn hàng P563: 29.471 đôi (tính đến tháng 10/2026) & đơn hàng vẫn còn đang nhận thêm\nNgoài ra, áp dụng được cho tất cả các dòng đế in logo khác','\n',char(10)),0,'https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790844524/jgwrtw8zuwdzlv9tdnlf.jpg,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790916067/fns8hmo41xnpqzptty8e.jpg','https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790845831/tx4ek43mvdojdr1bivg4.jpg,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790845829/y0huomigcubnfb1okvte.jpg,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790845830/pvvn3a8qaev3ftrurdv9.jpg','[{"type":"image","url":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790844524/jgwrtw8zuwdzlv9tdnlf.jpg","tag":"BEFORE"},{"type":"image","url":"https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790845831/tx4ek43mvdojdr1bivg4.jpg,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790845829/y0huomigcubnfb1okvte.jpg,https://res.cloudinary.com/dwl2xtbqa/image/upload/v1790845830/pvvn3a8qaev3ftrurdv9.jpg","tag":"AFTER"},{"type":"video_before","url":"https://res.cloudinary.com/dwl2xtbqa/video/upload/v1790841365/k3zo4rejx9prxx8gxwmh.mp4","title":"Video TRƯỚC Cải Tiến"},{"type":"video_after","url":"https://res.cloudinary.com/dwl2xtbqa/video/upload/v1790844577/l7a3pmyz2wz8f4jqkn6i.mp4","title":"Video SAU Cải Tiến"},{"type":"video_before","url":"https://res.cloudinary.com/dwl2xtbqa/video/upload/v1790841365/k3zo4rejx9prxx8gxwmh.mp4","title":"Video Trước Cải Tiến"},{"type":"video_after","url":"https://res.cloudinary.com/dwl2xtbqa/video/upload/v1790844577/l7a3pmyz2wz8f4jqkn6i.mp4","title":"Video Sau Cải Tiến"}]','SUBMITTED',NULL,0,0,0,0,34,NULL,3,'2026-10-01 09:16:17','2026-10-03 04:18:27','["TGĐ-001","PTGĐ-002","GĐ-003","PGĐ-004","202608001"]',NULL,NULL,NULL,NULL,'Cán bộ quản lý',10,2026,'','','','KZ-2026-HTD-DE-0001',215268,'TRI_GIA',0,0,0,'KZ-2026-HTD-DE-0001',NULL,'VP2_SKECHERS'